body {
  min-width: 850px;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
}

.wrapper {
  width: 90%;
  max-width: 1200px;
  margin-right: auto;
  margin-left: auto;
}

.header {
  position: relative;
  z-index: 0;
  padding-top: 15px;
  padding-bottom: 15px;
  color: white;
  text-align: center;
  background: url(./images/bkg.jpg) no-repeat center / cover;
}

.header::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  background-color: rgb(0 0 0 / 0.8);
}

.logo {
  color: inherit;
  text-transform: uppercase;
}

.logo:hover {
  color: #5f0dee;
}

.cta {
  padding: 25px;
  color: #fff;
  background-color: #000;
}

.cta-text {
  margin: 0;
}

.cta-button {
  margin-top: 30px;
  border: 1px solid #000;
  padding: 10px 65px;
  color: #000;
  font-family: inherit;
  font-weight: 800;
  font-size: inherit;
  text-transform: uppercase;
  background-color: #ffc802;
}

.cta-button:hover {
  box-shadow: inset 0 0 0 100px rgb(0 0 0 / 0.15);
  cursor: pointer;
}

.cta-button:focus {
  outline: 2px solid #000;
  outline-offset: 0;
}

.cta-button[disabled] {
  opacity: 0.6;
}

.title {
  margin: 100px 0;
  font-weight: 800;
  font-size: 45px;
  text-transform: uppercase;
}

/* Тут напишите правило для фрейма */

iframe {
  width: 100%;
  height: 500px;
}
